# Code generated by Claude
"""Velocity drive of the Tracer base: turns a Twist into free-joint velocities (moved out of experiments/combined_controller.py).

A Twist is the pair (forward speed along the base's own x axis in metres per second, yaw rate in radians per second).

The base is NOT driven through the wheel actuators: the mesh wheels have no traction in MuJoCo (see the BASE DRIVE
NOTE in experiments/combined_controller.py), so the free joint's velocity is written directly, on every physics step,
from the Twist.

    base_dof = find_base_dof(model)
    vx, vy, wz = twist_to_world_velocity(base_yaw(data), lin, ang)    # once per command update
    apply_base_velocity(data, base_dof, vx, vy, wz)                   # before every mj_step
"""

import math

import mujoco


def find_base_dof(model):
    """Finds the first free joint of the model, which is the Tracer base.

    Args:
        model (mujoco.MjModel): The compiled MuJoCo model.

    Returns:
        int or None: Address of the free joint's first degree of freedom (index into `data.qvel`), or None if the model has no free joint.
    """
    for j in range(model.njnt):
        if model.jnt_type[j] == mujoco.mjtJoint.mjJNT_FREE:
            return int(model.jnt_dofadr[j])
    return None


def base_yaw(data):
    """Computes the heading of the base from the free joint's orientation quaternion.

    Args:
        data (mujoco.MjData): Simulation state. The quaternion is read from `data.qpos[3:7]` (order w, x, y, z), so the base free joint must
            be the first joint of the model.

    Returns:
        float: Yaw angle about the world z axis, in radians, in the range -pi to pi.
    """
    qw, qx, qy, qz = data.qpos[3:7]
    return math.atan2(
        2.0 * (qw * qz + qx * qy),
        1.0 - 2.0 * (qy * qy + qz * qz))


def twist_to_world_velocity(yaw, lin_vel, ang_vel):
    """Projects the forward velocity into the world frame using the base yaw.

    Args:
        yaw (float): Heading of the base about the world z axis, in radians.
        lin_vel (float): Forward speed along the base's own x axis, in metres per second.
        ang_vel (float): Yaw rate, in radians per second.

    Returns:
        tuple of float: (base_vx, base_vy, base_wz): world-frame x velocity in metres per second, world-frame y velocity in metres per
        second, and yaw rate in radians per second (equal to `ang_vel`).
    """
    base_vx = lin_vel * math.cos(yaw)
    base_vy = lin_vel * math.sin(yaw)
    base_wz = ang_vel
    return base_vx, base_vy, base_wz


def apply_base_velocity(data, base_dof, base_vx, base_vy, base_wz):
    """Writes the commanded base velocity into the free joint's velocity (call before every `mujoco.mj_step`).

    Sets the world x and y velocity and the yaw rate. It also zeroes the roll and pitch angular velocity: without this, the wheel-floor
    contact friction opposes the forced linear velocity and creates a pitching torque that tips the robot over. The z velocity is left to
    physics (gravity, settling).

    Args:
        data (mujoco.MjData): Simulation state. `data.qvel` is modified in place.
        base_dof (int): Address of the base free joint's first degree of freedom, from `find_base_dof`.
        base_vx (float): World-frame x velocity in metres per second.
        base_vy (float): World-frame y velocity in metres per second.
        base_wz (float): Yaw rate about the world z axis in radians per second.
    """
    data.qvel[base_dof + 0] = base_vx
    data.qvel[base_dof + 1] = base_vy
    # qvel[base_dof + 2] (Z) left to physics
    data.qvel[base_dof + 3] = 0.0  # no roll
    data.qvel[base_dof + 4] = 0.0  # no pitch
    data.qvel[base_dof + 5] = base_wz
